134	
135	/* ── Card produto (comparação) ───────────────────────────────────── */
136	const ProdutoCompCard = ({ produto, i, navigate, onAdd }) => {
137	  const temPromo = produto.tags?.includes('promo') && produto.preco_promo != null;
138	  const preco = temPromo ? produto.preco_promo : produto.price;
139	  const rest = produto.restaurante;
140	  const restFechado = rest?.aparencia?.aberto === false;
141	  const [added, setAdded] = useState(false);
142	
143	  const handleClick = () => {
144	    if (!rest || restFechado) return;
145	    if (onAdd) {
146	      onAdd(produto, rest);
147	      setAdded(true);
148	      setTimeout(() => setAdded(false), 900);
149	    } else {
150	      navigate(`/r/${rest.slug}`);
151	    }
152	  };
153	
154	  return (
155	    <motion.button
156	      initial={{ opacity: 0, y: 16 }}
157	      animate={{ opacity: 1, y: 0 }}
158	      transition={{ delay: (i % 12) * 0.04, duration: 0.25 }}
159	      whileHover={restFechado ? {} : { y: -2, transition: { duration: 0.12 } }}
160	      onClick={handleClick}
161	      className={`bg-white rounded-2xl border overflow-hidden transition-all text-left w-full relative ${
162	        restFechado
163	          ? 'border-red-200 opacity-70 cursor-not-allowed'
164	          : added
165	          ? 'border-green-400 shadow-md shadow-green-100'
166	          : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/20'
167	      }`}
168	    >
169	      {added && (
170	        <div className="absolute inset-0 bg-green-500/10 z-10 flex items-center justify-center rounded-2xl pointer-events-none">
171	          <span className="bg-green-500 text-white text-xs font-black px-3 py-1 rounded-full shadow">✓ Adicionado!</span>
172	        </div>
173	      )}
174	      <div className="relative h-36 bg-[#F4F4F5] overflow-hidden">
175	        {produto.image_url
176	          ? <img src={produto.image_url} alt={produto.name} className={`w-full h-full object-cover ${restFechado ? 'grayscale' : ''}`} />
177	          : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={36} className="text-[#E4E4E7]" /></div>}
178	        {/* Tags */}
179	        <div className="absolute top-2 left-2 flex flex-col gap-1">
180	          {restFechado && (
181	            <span className="text-[10px] font-bold bg-red-500 text-white px-2 py-0.5 rounded-full shadow">Fechado</span>
182	          )}
183	          {!restFechado && temPromo && (
184	            <span className="text-[10px] font-bold bg-[#FF441F] text-white px-2 py-0.5 rounded-full shadow">PROMO</span>
185	          )}
186	        </div>
187	        {restFechado && (
188	          <div className="absolute inset-0 bg-white/30 flex items-end justify-center pb-3">
189	            <span className="text-[10px] font-bold bg-red-100 text-red-600 px-2 py-1 rounded-lg border border-red-200">
190	              Restaurante fechado
191	            </span>
192	          </div>
193	        )}
194	      </div>
195	      <div className="p-3">
196	        <p className="text-xs font-bold text-[#18181B] leading-tight line-clamp-2">{produto.name}</p>
197	        <div className="mt-1.5 flex items-center justify-between">
198	          <div>
199	            {!restFechado && temPromo && <p className="text-[10px] line-through text-[#71717A]">{fmt(produto.price)}</p>}
200	            <p className={`text-sm font-black ${restFechado ? 'text-[#71717A]' : temPromo ? 'text-green-600' : 'text-[#FF441F]'}`}>
201	              {restFechado ? 'Indisponível' : fmt(preco)}
202	            </p>
203	          </div>
204	        </div>
205	        {rest && (
206	          <div className="flex items-center gap-1.5 mt-2 pt-2 border-t border-[#F4F4F5]">
207	            <div className="w-5 h-5 rounded-md overflow-hidden bg-[#F4F4F5] flex-shrink-0">
208	              {rest.logo_url
209	                ? <img src={imgUrl(rest.logo_url)} alt={rest.name} className={`w-full h-full object-cover ${restFechado ? 'grayscale' : ''}`} />
210	                : <div className="w-full h-full flex items-center justify-center"><Icon name="Store" size={10} className="text-[#FF441F]/40" /></div>}
211	            </div>
212	            <p className="text-[10px] text-[#71717A] font-medium truncate">{rest.name}</p>
213	            {restFechado && <span className="text-[9px] text-red-500 font-bold flex-shrink-0">• Fechado</span>}
214	          </div>
215	        )}
216	      </div>
217	    </motion.button>
218	  );
219	};
220	
221	/* ── Carrossel restaurantes populares ────────────────────────────── */
222	const RestCarrossel = ({ restaurantes, navigate }) => {
223	  const scrollRef = useRef(null);
224	  const scroll = (dir) => {
225	    if (scrollRef.current) scrollRef.current.scrollBy({ left: dir * 220, behavior: 'smooth' });
226	  };
227	
228	  return (
229	    <div className="relative">
230	      <button onClick={() => scroll(-1)}
231	        className="absolute left-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -ml-4 hidden sm:flex">
232	        <Icon name="ChevronLeft" size={16} className="text-[#27272A]" />
233	      </button>
234	      <div ref={scrollRef}
235	        className="flex gap-4 overflow-x-auto pb-2 scroll-smooth"
236	        style={{ scrollbarWidth: 'none' }}>
237	        {restaurantes.map((r, i) => (
238	          <motion.button
239	            key={r.id}
240	            initial={{ opacity: 0, scale: 0.9 }}
241	            animate={{ opacity: 1, scale: 1 }}
242	            transition={{ delay: i * 0.07 }}
243	            whileHover={{ scale: 1.05 }}
244	            onClick={() => navigate(`/r/${r.slug}`)}
245	            className="flex-shrink-0 flex flex-col items-center gap-2 w-20 sm:w-24"
246	          >
247	            <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-2xl overflow-hidden bg-white border-2 border-[#E4E4E7] hover:border-[#FF441F]/40 shadow-sm transition-all">
248	              {r.logo_url
249	                ? <img src={imgUrl(r.logo_url)} alt={r.name} className="w-full h-full object-cover" />
250	                : <div className="w-full h-full bg-gradient-to-br from-[#FF441F]/10 to-[#FF7A00]/20 flex items-center justify-center">
251	                    <Icon name="Store" size={28} className="text-[#FF441F]/40" />
252	                  </div>}
253	            </div>
254	            <p className="text-[10px] sm:text-xs font-semibold text-[#27272A] text-center line-clamp-2 leading-tight px-1">{r.name}</p>
255	          </motion.button>
256	        ))}
257	      </div>
258	      <button onClick={() => scroll(1)}
259	        className="absolute right-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -mr-4 hidden sm:flex">
260	        <Icon name="ChevronRight" size={16} className="text-[#27272A]" />
261	      </button>
262	    </div>
263	  );
264	};
265	
266	/* ── Card produto carrossel ──────────────────────────────────────── */
267	const ProdCarrosselCard = ({ produto, i, navigate, onAdd }) => {
268	  const temPromo = produto.tags?.includes('promo') && produto.preco_promo != null;
269	  const preco = temPromo ? produto.preco_promo : produto.price;
270	  const rest = produto.restaurante;
271	  const fechado = rest?.aparencia?.aberto === false;
272	  const [added, setAdded] = useState(false);
273	
274	  const handleClick = () => {
275	    if (!rest || fechado) return;
276	    if (onAdd) {
277	      onAdd(produto, rest);
278	      setAdded(true);
279	      setTimeout(() => setAdded(false), 900);
280	    } else {
281	      navigate(`/r/${rest.slug}`);
282	    }
283	  };
284	
285	  return (
286	    <motion.button
287	      initial={{ opacity: 0, scale: 0.9 }}
288	      animate={{ opacity: 1, scale: 1 }}
289	      transition={{ delay: (i % 10) * 0.05 }}
290	      whileHover={{ y: fechado ? 0 : -2 }}
291	      onClick={handleClick}
292	      className={`flex-shrink-0 w-36 sm:w-40 bg-white rounded-2xl border overflow-hidden text-left relative ${
293	        fechado ? 'border-red-200 opacity-70' : added ? 'border-green-400' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/30'
294	      }`}
295	    >
296	      {added && (
297	        <div className="absolute inset-0 bg-green-500/20 z-10 flex items-center justify-center rounded-2xl pointer-events-none">
298	          <span className="bg-green-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full">✓</span>
299	        </div>
300	      )}
301	      <div className="relative h-28 bg-[#F4F4F5]">
302	        {produto.image_url
303	          ? <img src={produto.image_url} alt={produto.name} className={`w-full h-full object-cover ${fechado ? 'grayscale' : ''}`} />
304	          : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={28} className="text-[#E4E4E7]" /></div>}
305	        {!fechado && temPromo && (
306	          <span className="absolute top-2 left-2 text-[9px] font-bold bg-[#FF441F] text-white px-1.5 py-0.5 rounded-full shadow">PROMO</span>
307	        )}
308	        {produto.tags?.includes('mais_vendido') && (
309	          <span className="absolute top-2 right-2 text-[9px] font-bold bg-amber-500 text-white px-1.5 py-0.5 rounded-full shadow">🔥</span>
310	        )}
311	      </div>
312	      <div className="p-2.5">
313	        <p className="text-xs font-bold text-[#18181B] line-clamp-2 leading-tight">{produto.name}</p>
314	        <div className="mt-1.5">
315	          {temPromo && <p className="text-[9px] line-through text-[#71717A]">{fmt(produto.price)}</p>}
316	          <p className={`text-sm font-black ${fechado ? 'text-[#71717A]' : temPromo ? 'text-green-600' : 'text-[#FF441F]'}`}>
317	            {fechado ? '–' : fmt(preco)}
318	          </p>
319	        </div>
320	        {rest && <p className="text-[9px] text-[#71717A] truncate mt-1">{rest.name}</p>}
321	      </div>
322	    </motion.button>
323	  );
324	};
325	
326	/* ── Carrossel de produtos ────────────────────────────────────────── */
327	const ProdCarrossel = ({ produtos, navigate, onAdd }) => {
328	  const scrollRef = useRef(null);
329	  const scroll = (dir) => {
330	    if (scrollRef.current) scrollRef.current.scrollBy({ left: dir * 200, behavior: 'smooth' });
331	  };
332	
333	  return (
334	    <div className="relative">
335	      <button onClick={() => scroll(-1)}
336	        className="absolute left-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -ml-4 hidden sm:flex">
